using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

namespace JLinkDev.ProceduralNebulae
{
    /// <summary>Runs the configured feature on this camera in a URP scene.</summary>
    [ExecuteAlways, DisallowMultipleComponent, RequireComponent(typeof(Camera), typeof(UniversalAdditionalCameraData))]
    public sealed class NebulaCameraPass : MonoBehaviour
    {
        public NebulaRendererFeature feature;
        private Camera view;
        private UniversalAdditionalCameraData cameraData;
        private NebulaRendererFeature instance, source;

#if UNITY_EDITOR
        private int sourceRevision;
#endif

        internal bool HandlesCamera => isActiveAndEnabled && view && cameraData && feature && feature.isActive &&
            view.cameraType == CameraType.Game && !view.stereoEnabled && cameraData.renderType == CameraRenderType.Base;

        private void OnEnable()
        {
            view = GetComponent<Camera>();
            cameraData = GetComponent<UniversalAdditionalCameraData>();
            RenderPipelineManager.beginCameraRendering += BeginCamera;
        }

        private void BeginCamera(ScriptableRenderContext context, Camera camera)
        {
            if (camera != view || !HandlesCamera || !(RenderPipelineManager.currentPipeline is UniversalRenderPipeline)) return;
            bool refresh = source != feature;
#if UNITY_EDITOR
            int revision = UnityEditor.EditorUtility.GetDirtyCount(feature);
            refresh |= revision != sourceRevision;
            sourceRevision = revision;
#endif
            if (refresh)
            {
                Release();
                // URP initializes the clone in ScriptableRendererFeature.OnEnable.
                instance = Instantiate(feature);
                instance.hideFlags = HideFlags.HideAndDontSave;
                source = feature;
            }
            instance.Enqueue(cameraData.scriptableRenderer, camera);
        }

        private void OnDisable()
        {
            RenderPipelineManager.beginCameraRendering -= BeginCamera;
            Release();
        }

        private void Release()
        {
            if (instance) instance.Dispose();
            CoreUtils.Destroy(instance);
            instance = null;
            source = null;
        }
    }
}
